-- CommunityMapper.selectCommunityCount SELECT COUNT(*) FROM board b
AND b.title LIKE CONCAT('%', #{title}, '%')
AND u.name = #{name}

-- CommunityMapper.selectCommunityList SELECT b.id ,b.user_id ,b.title ,b.content ,b.isbn ,b.view_count ,b.create_dt ,b.update_dt ,u.email ,u.name FROM board b INNER JOIN public.user u ON b.user_id = u.id
AND b.title LIKE CONCAT('%', #{title}, '%')
AND u.name = #{name}
ORDER BY b.id DESC LIMIT #{size} OFFSET #{offset}

